	array( 'title' => 'Skellig Michael', 'slug' => 'skellig-michael', 'county' => 'Kerry', 'town' => 'Portmagee', 'category' => 'Ilhas', 'official_website' => 'https://heritageireland.ie/places-to-visit/skellig-michael/', 'discover_ireland' => '', 'excerpt' => 'Patrimônio Mundial da UNESCO: mosteiro do século VI no topo de ilha rochosa no Atlântico, cenário de Star Wars.', 'content' => '<p>Skellig Michael abriga um mosteiro cristão primitivo construído em degraus de pedra a 180 metros acima do mar. O acesso é limitado a barcos licenciados entre maio e outubro, com reservas muito concorridas.</p>', 'outdoor' => true, 'booking' => true ),
	array( 'title' => 'Valentia Island', 'slug' => 'valentia-island', 'county' => 'Kerry', 'town' => 'Cahersiveen', 'category' => 'Ilhas', 'official_website' => 'https://valentiaisland.ie/', 'discover_ireland' => 'https://www.discoverireland.ie/valentia-island', 'excerpt' => 'Ilha conectada por ponte e ferry, com pegadas de dinossauro, jardins subtropicais e o farol de Cromwell Point.', 'content' => '<p>Valentia Island combina natureza e história: as pegadas fósseis de tetrápodes estão entre as mais antigas do mundo, e a ilha sediou o primeiro cabo telegráfico transatlântico da Europa à América.</p>', 'outdoor' => true, 'family' => true ),
	array( 'title' => 'Kerry Cliffs', 'slug' => 'kerry-cliffs', 'county' => 'Kerry', 'town' => 'Portmagee', 'category' => 'Natureza', 'official_website' => '', 'discover_ireland' => 'https://www.discoverireland.ie/kerry/kerry-cliffs', 'excerpt' => 'Falésias de mais de 300 metros com vista para Skellig Michael, no Anel de Skellig.', 'content' => '<p>Os Kerry Cliffs oferecem o melhor mirante para as ilhas Skellig, a partir de plataformas seguras sobre penhascos que caem direto no Atlântico. Um dos pontos mais dramáticos do Ring of Kerry.</p>', 'outdoor' => true ),
	array( 'title' => 'Derrynane House & National Historic Park', 'slug' => 'derrynane-house', 'county' => 'Kerry', 'town' => 'Caherdaniel', 'category' => 'História', 'official_website' => 'https://heritageireland.ie/places-to-visit/daniel-oconnell-house-derrynane-house/', 'discover_ireland' => 'https://www.discoverireland.ie/kerry/derrynane-house', 'excerpt' => 'Casa de Daniel O\'Connell, o Libertador, dentro de um parque costeiro com praia e jardins subtropicais.', 'content' => '<p>Derrynane House preserva memórias de Daniel O\'Connell, campeão da emancipação católica. O parque ao redor inclui a praia de Derrynane, trilhas litorâneas e jardins com plantas raras.</p>', 'outdoor' => true ),
	array( 'title' => 'Gallarus Oratory', 'slug' => 'gallarus-oratory', 'county' => 'Kerry', 'town' => 'Dingle', 'category' => 'História', 'official_website' => '', 'discover_ireland' => '', 'excerpt' => 'Oratório cristão primitivo em pedra seca, com mais de 1.200 anos, em forma de casco de barco invertido.', 'content' => '<p>Gallarus Oratory é o exemplo mais bem preservado de arquitetura cristã primitiva da Irlanda. Suas paredes de pedra sem argamassa permanecem impermeáveis há mais de mil anos.</p>', 'outdoor' => true ),
	array( 'title' => 'Muckross Abbey', 'slug' => 'muckross-abbey', 'county' => 'Kerry', 'town' => 'Killarney', 'category' => 'História', 'official_website' => '', 'discover_ireland' => '', 'excerpt' => 'Abadia franciscana do século XV com claustro e um enorme teixo central, no coração do parque nacional.', 'content' => '<p>Muckross Abbey foi fundada por volta de 1448 e várias vezes saqueada e reconstruída. Poetas e chefes gaélicos estão enterrados em seu cemitério. Acesso livre a pé ou de bicicleta a partir de Muckross House.</p>', 'outdoor' => true, 'free' => true ),
	array( 'title' => 'Banna Strand', 'slug' => 'banna-strand', 'county' => 'Kerry', 'town' => 'Ardfert', 'category' => 'Praias', 'official_website' => '', 'discover_ireland' => 'https://www.discoverireland.ie/kerry/banna-strand', 'excerpt' => 'Praia extensa de areia dourada ao norte de Tralee, com dunas e águas ideais para surf e banho.', 'content' => '<p>Banna Strand se estende por cerca de 10 km e é famosa pelo desembarque de Roger Casement em 1916. Hoje é uma praia popular para famílias, surfistas e caminhadas com vista para o Atlântico.</p>', 'outdoor' => true, 'family' => true, 'free' => true ),

	// ---- LAOIS (+6) ----
	array( 'title' => 'Rock of Dunamase', 'slug' => 'rock-of-dunamase', 'county' => 'Laois', 'town' => 'Stradbally', 'category' => 'Castelos', 'official_website' => '', 'discover_ireland' => 'https://www.discoverireland.ie/laois/rock-of-dunamase', 'excerpt' => 'Fortaleza normanda em ruínas sobre afloramento rochoso, com vistas de 360° pelo interior de Laois.', 'content' => '<p>O Rock of Dunamase domina a planície de Laois desde o século IX. A fortaleza, associada ao casamento de Strongbow e Aoife, é de acesso livre e oferece um dos mirantes mais impressionantes do midlands.</p>', 'outdoor' => true, 'free' => true ),
	array( 'title' => 'Emo Court', 'slug' => 'emo-court', 'county' => 'Laois', 'town' => 'Emo', 'category' => 'Jardins', 'official_website' => 'https://heritageireland.ie/places-to-visit/emo-court/', 'discover_ireland' => 'https://www.discoverireland.ie/laois/emo-court', 'excerpt' => 'Mansão neoclássica do século XVIII com jardins e lago desenhados por Capability Brown; entrada gratuita.', 'content' => '<p>Emo Court foi projetada por James Gandon (arquiteto do Custom House de Dublin) e seus terrenos incluem um lago formal atribuído a Capability Brown. A casa pode ser visitada em tours guiados gratuitos.</p>', 'outdoor' => true, 'free' => true ),
	array( 'title' => 'Heywood Gardens', 'slug' => 'heywood-gardens', 'county' => 'Laois', 'town' => 'Ballinakill', 'category' => 'Jardins', 'official_website' => 'https://heritageireland.ie/places-to-visit/heywood-gardens/', 'discover_ireland' => 'https://www.discoverireland.ie/laois/heywood-gardens', 'excerpt' => 'Jardins formais dos séculos XVIII/XIX com terraços, lago e o famoso "jardim secreto" circular.', 'content' => '<p>Os Heywood Gardens combinam um jardim paisagístico do século XVIII com terraços formais projetados por Edwin Lutyens em 1906, incluindo um jardim circular murado de grande charme.</p>', 'outdoor' => true, 'free' => true ),
	array( 'title' => 'Timahoe Round Tower', 'slug' => 'timahoe-round-tower', 'county' => 'Laois', 'town' => 'Timahoe', 'category' => 'História', 'official_website' => '', 'discover_ireland' => 'https://www.discoverireland.ie/laois/timahoe-round-tower', 'excerpt' => 'Torre redonda do século XII considerada uma das mais belas da Irlanda, com portal ricamente decorado.', 'content' => '<p>A torre redonda de Timahoe ergue-se quase 30 metros sobre um mosteiro do século VII fundado por São Mochua. Seu portal esculpido com cabeças humanas é único entre as torres irlandesas.</p>', 'outdoor' => true, 'free' => true ),
	array( 'title' => 'Abbeyleix Heritage House', 'slug' => 'abbeyleix-heritage-house', 'county' => 'Laois', 'town' => 'Abbeyleix', 'category' => 'Museus', 'official_website' => 'https://abbeyleixheritage.com/', 'discover_ireland' => 'https://www.discoverireland.ie/laois/abbeyleix-heritage-house', 'excerpt' => 'Centro de patrimônio que conta a história planejada da vila georgiana de Abbeyleix e do tapete local.', 'content' => '<p>Abbeyleix foi uma das primeiras vilas planejadas da Irlanda. O Heritage House documenta sua história, a indústria do tapete Abbeyleix e a vida rural do midlands, com exposições e arquivo local.</p>', 'indoor' => true ),
	array( 'title' => 'Slieve Bloom Mountains', 'slug' => 'slieve-bloom-mountains', 'county' => 'Laois', 'town' => 'Clonaslee / Cadamstown', 'category' => 'Natureza', 'official_website' => 'https://slievebloom.ie/', 'discover_ireland' => '', 'excerpt' => 'Montanhas de turfeira e floresta entre Laois e Offaly, com trilhas, cachoeiras e mirantes panorâmicos.', 'content' => '<p>As Slieve Bloom Mountains oferecem algumas das caminhadas mais tranquilas da Irlanda central, com rotas marcadas, o Glenbarrow Waterfall e vistas que alcançam metade do país em dias claros.</p>', 'outdoor' => true, 'free' => true ),

	// ---- OFFALY (+5) ----
	array( 'title' => 'Clonmacnoise', 'slug' => 'clonmacnoise', 'county' => 'Offaly', 'town' => 'Shannonbridge', 'category' => 'História', 'official_website' => 'https://heritageireland.ie/places-to-visit/clonmacnoise/', 'discover_ireland' => 'https://www.discoverireland.ie/offaly/clonmacnoise', 'excerpt' => 'Um dos mosteiros mais importantes da Europa medieval, às margens do rio Shannon, com torres redondas e alta cruzes.', 'content' => '<p>Fundado por São Ciarán em 545, Clonmacnoise foi um grande centro de aprendizado e peregrinação. O sítio reúne duas torres redondas, sete igrejas, três alta cruzes e um museu com lápidas célticas.</p>', 'outdoor' => true ),
	array( 'title' => 'Birr Castle Demesne', 'slug' => 'birr-castle-demesne', 'county' => 'Offaly', 'town' => 'Birr', 'category' => 'Jardins', 'official_website' => 'https://birrcastle.com/', 'discover_ireland' => '', 'excerpt' => 'Propriedade científica dos Parsons com jardins premiados, o telescópio gigante do século XIX e centro de ciência.', 'content' => '<p>Birr Castle combina um jardim histórico excepcional com o Leviatã de Parsonstown — por décadas o maior telescópio do mundo — e um centro de ciência interativo. A família Parsons ainda vive no castelo.</p>', 'outdoor' => true, 'family' => true ),
	array( 'title' => 'Lough Boora Discovery Park', 'slug' => 'lough-boora-discovery-park', 'county' => 'Offaly', 'town' => 'Boora', 'category' => 'Natureza', 'official_website' => 'https://loughboora.com/', 'discover_ireland' => 'https://www.discoverireland.ie/offaly/lough-boora-discovery-park', 'excerpt' => 'Parque de turfeiras regeneradas com esculturas ao ar livre, trilhas de caminhada e ciclismo e aves raras.', 'content' => '<p>Lough Boora transformou antigas turfeiras industriais num parque de 2.000 hectares com esculturas monumentais, trilhas planas para todas as idades e observação de aves como o peneireiro e o maçarico.</p>', 'outdoor' => true, 'family' => true, 'free' => true ),
	array( 'title' => 'Charleville Forest Castle', 'slug' => 'charleville-forest-castle', 'county' => 'Offaly', 'town' => 'Tullamore', 'category' => 'Castelos', 'official_website' => '', 'discover_ireland' => '', 'excerpt' => 'Castelo neogótico do século XIX cercado por floresta antiga de carvalhos, com tours e eventos.', 'content' => '<p>Charleville Forest Castle é um dos castelos góticos mais atmosféricos da Irlanda, imortalizado em fotos e filmes. A floresta ao redor guarda alguns dos carvalhos mais antigos do país.</p>', 'outdoor' => true ),
	array( 'title' => 'Tullamore D.E.W. Experience', 'slug' => 'tullamore-dew-experience', 'county' => 'Offaly', 'town' => 'Tullamore', 'category' => 'Cultura', 'official_website' => 'https://www.tullamoredew.com/en-gb/visit-tullamore-dew/', 'discover_ireland' => '', 'excerpt' => 'Centro de visitantes do whisky Tullamore D.E.W. num armazém do século XIX, com degustações guiadas.', 'content' => '<p>Nos antigos bond stores de Tullamore, o centro de visitantes narra a história do blended whiskey irlandês criado em 1829, terminando com uma degustação comparativa de três rótulos.</p>', 'indoor' => true ),

	// ---- WESTMEATH (+5) ----
	array( 'title' => 'Belvedere House Gardens & Park', 'slug' => 'belvedere-house-gardens', 'county' => 'Westmeath', 'town' => 'Mullingar', 'category' => 'Jardins', 'official_website' => 'https://belvedere-house.ie/', 'discover_ireland' => '', 'excerpt' => 'Casa de campo do século XVIII com jardins, folly "Jealous Wall" e eventos familiares o ano inteiro.', 'content' => '<p>Belvedere House fica às margens do Lough Ennell e é famosa pela Jealous Wall — a maior folly da Irlanda, construída por um irmão para bloquear a vista da mansão vizinha. O parque tem playground e trilhas.</p>', 'outdoor' => true, 'family' => true ),
	array( 'title' => 'Athlone Castle Visitor Centre', 'slug' => 'athlone-castle', 'county' => 'Westmeath', 'town' => 'Athlone', 'category' => 'Castelos', 'official_website' => 'https://www.athlonecastle.ie/', 'discover_ireland' => 'https://www.discoverireland.ie/westmeath/athlone-castle', 'excerpt' => 'Castelo normando do século XII no rio Shannon, com museu interativo sobre o cerco de Athlone.', 'content' => '<p>Athlone Castle guarda a travessia estratégica do Shannon desde 1129. O centro de visitantes usa exposições interativas para contar o cerco de 1691 e a história militar e civil da cidade.</p>', 'indoor' => true, 'family' => true ),
	array( 'title' => 'Kilbeggan Distillery Experience', 'slug' => 'kilbeggan-distillery', 'county' => 'Westmeath', 'town' => 'Kilbeggan', 'category' => 'Cultura', 'official_website' => 'https://www.kilbeggandistillery.com/', 'discover_ireland' => '', 'excerpt' => 'Destilaria licenciada mais antiga do mundo (1757), com moinho a vapor funcionando e degustações.', 'content' => '<p>A Kilbeggan Distillery produz whiskey desde 1757. O tour mostra o processo tradicional, o motor a vapor de 1870 em operação e termina com degustação no bar de 200 anos.</p>', 'indoor' => true ),
	array( 'title' => 'Mullaghmeen Forest', 'slug' => 'mullaghmeen-forest', 'county' => 'Westmeath', 'town' => 'Castlepollard', 'category' => 'Natureza', 'official_website' => '', 'discover_ireland' => '', 'excerpt' => 'Grande floresta de folhosas plantadas, com trilhas e vista para o Lough Derravaragh.', 'content' => '<p>Mullaghmeen cobre colinas de faia, freixo e bétula com rotas marcadas até o ponto mais alto de Westmeath. Ao lado fica o Lough Derravaragh, cenário da lenda dos Filhos de Lir.</p>', 'outdoor' => true, 'free' => true ),
	array( 'title' => 'Glendeer Pet Farm', 'slug' => 'glendeer-pet-farm', 'county' => 'Westmeath', 'town' => 'Athlone', 'category' => 'Vida Selvagem', 'official_website' => 'https://glendeerpetfarm.ie/', 'discover_ireland' => '', 'excerpt' => 'Fazenda de animais aberta ao público com cabras, cordeiros, aves e playground coberto.', 'content' => '<p>Glendeer Pet Farm é um programa clássico de dia chuvoso ou ensolarado para famílias com crianças pequenas: alimentação de animais, tratores de brinquedo e área interna coberta.</p>', 'outdoor' => true, 'family' => true ),

	// ---- LONGFORD (+6) ----
	array( 'title' => 'Corlea Trackway Visitor Centre', 'slug' => 'corlea-trackway', 'county' => 'Longford', 'town' => 'Kenagh', 'category' => 'História', 'official_website' => 'https://heritageireland.ie/places-to-visit/corlea-trackway-visitor-centre/', 'discover_ireland' => '', 'excerpt' => 'Centro que protege uma estrada de carvalho de 2.000 anos construída sobre a turfeira, única na Europa.', 'content' => '<p>A Corlea Trackway foi construída em 148 a.C. e é a maior via de madeira pré-histórica já descoberta na Europa. O centro de visitantes permite ver a estrada original preservada no ambiente úmido.</p>', 'indoor' => true ),
	array( 'title' => 'Ardagh Heritage Village', 'slug' => 'ardagh-heritage-village', 'county' => 'Longford', 'town' => 'Ardagh', 'category' => 'Cidades', 'official_website' => '', 'discover_ireland' => '', 'excerpt' => 'Vila vencedora de prêmios de conservação, com verde central pitoresco e centro de interpretação.', 'content' => '<p>Ardagh é frequentemente citada como uma das vilas mais bonitas da Irlanda, com seu verde cercado por edifícios do século XVIII. O centro de patrimônio explica a história local e o tesouro de Ardagh.</p>', 'outdoor' => true, 'free' => true ),
	array( 'title' => 'Granard Motte & Bailey', 'slug' => 'granard-motte-bailey', 'county' => 'Longford', 'town' => 'Granard', 'category' => 'História', 'official_website' => '', 'discover_ireland' => '', 'excerpt' => 'Motte normanda do século XII sobre morro antigo, com estátua de Santa Kitirine e vistas amplas.', 'content' => '<p>A motte de Granard, erguida por Richard de Tuite em 1199, coroa um morro usado desde a Idade do Ferro. Do topo, avistam-se os condados vizinhos em todos os horizontes.</p>', 'outdoor' => true, 'free' => true ),
	array( 'title' => 'Royal Canal Greenway', 'slug' => 'royal-canal-greenway', 'county' => 'Longford', 'town' => 'Cloondara', 'category' => 'Greenways', 'official_website' => '', 'discover_ireland' => '', 'excerpt' => 'Greenway de 130 km ao longo do Royal Canal, de Dublin a Cloondara — o trecho final fica em Longford.', 'content' => '<p>O Royal Canal Greenway acompanha o canal do século XVIII por 130 km planos, ideais para bicicleta. O marco final fica em Cloondara, onde o canal encontra o rio Shannon.</p>', 'outdoor' => true, 'free' => true ),
	array( 'title' => 'Newcastle Wood', 'slug' => 'newcastle-wood', 'county' => 'Longford', 'town' => 'Ballymahon', 'category' => 'Natureza', 'official_website' => '', 'discover_ireland' => '', 'excerpt' => 'Floresta de coníferas e folhosas com trilhas tranquilas perto de Ballymahon.', 'content' => '<p>Newcastle Wood oferece caminhadas sombreadas e observação de vida silvestre a poucos minutos de Ballymahon, no coração rural de Longford.</p>', 'outdoor' => true, 'free' => true ),
	array( 'title' => 'Lough Ree', 'slug' => 'lough-ree', 'county' => 'Longford', 'town' => 'Lanesborough', 'category' => 'Natureza', 'official_website' => '', 'discover_ireland' => '', 'excerpt' => 'Grande lago do rio Shannon com ilhas, pesca, passeios de barco e praias fluviais.', 'content' => '<p>Lough Ree ("lago dos reis") é o segundo maior lago do Shannon, compartilhado por Longford, Westmeath e Roscommon. De Lanesborough e Ballyleague partem cruzeiros e rotas de pesca famosas.</p>', 'outdoor' => true, 'free' => true ),

	// ---- ROSCOMMON (+6) ----
	array( 'title' => 'Rathcroghan', 'slug' => 'rathcroghan', 'county' => 'Roscommon', 'town' => 'Tulsk', 'category' => 'História', 'official_website' => 'https://rathcroghan.ie/', 'discover_ireland' => '', 'excerpt' => 'Capital real antiga de Connacht e porta de entrada para o outro mundo na mitologia irlandesa.', 'content' => '<p>Rathcroghan (Ráth Crúachan) foi sede dos reis de Connacht e palco do épico Táin Bó Cúailnge. O centro de visitantes em Tulsk organiza tours arqueológicos pelos monumentos e pela caverna de Oweynagat.</p>', 'indoor' => true, 'outdoor' => true ),
	array( 'title' => 'Boyle Abbey', 'slug' => 'boyle-abbey', 'county' => 'Roscommon', 'town' => 'Boyle', 'category' => 'História', 'official_website' => 'https://heritageireland.ie/places-to-visit/boyle-abbey/', 'discover_ireland' => 'https://www.discoverireland.ie/roscommon/boyle-abbey', 'excerpt' => 'Abadia cisterciense do século XII com claustro impressionante, no coração de Boyle.', 'content' => '<p>Fundada em 1161, Boyle Abbey é uma das mais bem preservadas fundações cistercienses de Connacht, com arcadas românicas e góticas lado a lado no claustro.</p>', 'outdoor' => true ),
	array( 'title' => 'Strokestown Park & National Famine Museum', 'slug' => 'strokestown-park-famine-museum', 'county' => 'Roscommon', 'town' => 'Strokestown', 'category' => 'Museus', 'official_website' => 'https://strokestownpark.ie/', 'discover_ireland' => '', 'excerpt' => 'Mansão georgiana com o Museu Nacional da Grande Fome e jardins murados restaurados.', 'content' => '<p>Strokestown Park preserva a casa senhorial intacta e abriga o National Famine Museum, referência internacional sobre a Grande Fome de 1845-52. Os jardins murados de 4 acres estão entre os maiores da Irlanda.</p>', 'indoor' => true, 'outdoor' => true ),
	array( 'title' => 'Arigna Mining Experience', 'slug' => 'arigna-mining-experience', 'county' => 'Roscommon', 'town' => 'Arigna', 'category' => 'Museus', 'official_website' => 'https://www.arignaminingexperience.ie/', 'discover_ireland' => 'https://www.discoverireland.ie/roscommon/arigna-mining-experience', 'excerpt' => 'Tour guiado por mina de carvão real conduzido por ex-mineradores, nas colinas de Arigna.', 'content' => '<p>Na última mina de carvão da Irlanda, ex-trabalhadores guiam visitantes pelos túneis explicando 400 anos de mineração. Uma experiência autêntica e tocante da história industrial irlandesa.</p>', 'indoor' => true, 'booking' => true ),
	array( 'title' => 'Lough Key Forest & Activity Park', 'slug' => 'lough-key-forest-park', 'county' => 'Roscommon', 'town' => 'Boyle', 'category' => 'Natureza', 'official_website' => 'https://loughkey.ie/', 'discover_ireland' => '', 'excerpt' => 'Parque florestal com ilhas, torre de observação, zip line, bungalows e trilhas para todas as idades.', 'content' => '<p>Lough Key combina 350 hectares de floresta e lago com atrações como a Moylurg Viewing Tower, o Zipit Forest Adventures e o Boda Borg — desafios indoor em equipe. Um dos parques mais completos do oeste.</p>', 'outdoor' => true, 'family' => true ),
	array( 'title' => 'Roscommon Castle', 'slug' => 'roscommon-castle', 'county' => 'Roscommon', 'town' => 'Roscommon', 'category' => 'Castelos', 'official_website' => '', 'discover_ireland' => 'https://www.discoverireland.ie/roscommon/roscommon-castle', 'excerpt' => 'Castelo normando do século XIII em ruínas evocativas, com parque público e lago ao redor.', 'content' => '<p>Construído por Robert de Ufford em 1269, o Roscommon Castle mudou de mãos várias vezes entre irlandeses e ingleses. Hoje integra um parque municipal com trilhas e o Loughnaneane Park.</p>', 'outdoor' => true, 'free' => true ),

	// ---- LEITRIM (+6) ----
	array( 'title' => 'Glencar Waterfall', 'slug' => 'glencar-waterfall', 'county' => 'Leitrim', 'town' => 'Manorhamilton', 'category' => 'Natureza', 'official_website' => '', 'discover_ireland' => 'https://www.discoverireland.ie/leitrim/glencar-waterfall', 'excerpt' => 'Cascata de 15 metros imortalizada por W.B. Yeats, perto de Sligo, com trilha curta e área de piquenique.', 'content' => '<p>Glencar Waterfall inspirou o poema "The Stolen Child" de Yeats. A queda d\'água fica a poucos minutos de carro do Lough Gill, com passarela fácil de acesso e ambiente de floresta encantada.</p>', 'outdoor' => true, 'family' => true, 'free' => true ),
	array( 'title' => "Parke's Castle", 'slug' => 'parkes-castle', 'county' => 'Leitrim', 'town' => 'Dromahair', 'category' => 'Castelos', 'official_website' => 'https://heritageireland.ie/places-to-visit/parkes-castle/', 'discover_ireland' => '', 'excerpt' => 'Castelo-forte do século XVII restaurado às margens do Lough Gill, com exposição sobre o plantation.', 'content' => '<p>Parke\'s Castle foi erguido sobre uma torre anterior dos O\'Rourke, reis de Breifne. Restaurado com pedra original, oferece exposições e vista privilegiada do Lough Gill.</p>', 'outdoor' => true ),
	array( 'title' => 'Acres Lake Floating Boardwalk', 'slug' => 'acres-lake-floating-boardwalk', 'county' => 'Leitrim', 'town' => 'Drumshanbo', 'category' => 'Caminhadas', 'official_website' => '', 'discover_ireland' => '', 'excerpt' => 'Passarela flutuante de 600 m sobre o Lough Allen, parte do Shannon Blueway, com trilhas e caiaque.', 'content' => '<p>A Acres Lake Floating Boardwalk é a primeira passarela flutuante da Irlanda, ligando Drumshanbo ao Lough Allen. Integra o Shannon Blueway, rede de trilhas aquáticas e terrestres.</p>', 'outdoor' => true, 'family' => true, 'free' => true ),
	array( 'title' => 'Lough Allen', 'slug' => 'lough-allen', 'county' => 'Leitrim', 'town' => 'Drumshanbo', 'category' => 'Natureza', 'official_website' => '', 'discover_ireland' => '', 'excerpt' => 'Lago serrilhado no alto do Shannon, cercado pelas montanhas de Arigna e Sliabh an Iarainn.', 'content' => '<p>Lough Allen é o primeiro grande lago do rio Shannon, com praias discretas, mirantes e rotas de caiaque. As montanhas ao redor guardam paisagens de turfeira pouco exploradas.</p>', 'outdoor' => true, 'free' => true ),
	array( 'title' => 'Lough Rynn Castle Gardens', 'slug' => 'lough-rynn-castle-gardens', 'county' => 'Leitrim', 'town' => 'Mohill', 'category' => 'Jardins', 'official_website' => '', 'discover_ireland' => '', 'excerpt' => 'Jardins históricos da propriedade dos Clements, com labirinto, walled garden e vista para o lago.', 'content' => '<p>Os terrenos de Lough Rynn, antiga sede dos condes de Leitrim, incluem jardins murados restaurados, um labirinto e trilhas à beira do lago. A propriedade funciona hoje como hotel, mas os jardins recebem visitantes.</p>', 'outdoor' => true, 'family' => true ),
	array( 'title' => 'Seán Mac Diarmada Cottage', 'slug' => 'sean-mac-diarmada-cottage', 'county' => 'Leitrim', 'town' => 'Kiltyclogher', 'category' => 'História', 'official_website' => '', 'discover_ireland' => '', 'excerpt' => 'Casa natal de um dos signatários da Proclamação de 1916, preservada como museu no norte de Leitrim.', 'content' => '<p>Seán Mac Diarmada, executado após o Levante da Páscoa de 1916, nasceu nesta casa de pedra típica. O sítio preserva mobiliário de época e conta a trajetória do líder republicano.</p>', 'outdoor' => true ),

	// ---- CAVAN (+6) ----
	array( 'title' => 'Cavan Burren Park', 'slug' => 'cavan-burren-park', 'county' => 'Cavan', 'town' => 'Blacklion', 'category' => 'Natureza', 'official_website' => '', 'discover_ireland' => 'https://www.discoverireland.ie/cavan/cavan-burren-park', 'excerpt' => 'Paisagem cárstica com megálitos, dolmens e trilhas interpretativas no Geoparque Global Marble Arch Caves.', 'content' => '<p>O Cavan Burren Park guarda um dos conjuntos megalíticos mais acessíveis da Irlanda, com rotas curtas e painéis explicativos. Faz parte do Geoparque Global UNESCO Marble Arch Caves.</p>', 'outdoor' => true, 'family' => true, 'free' => true ),
	array( 'title' => 'Killykeen Forest Park', 'slug' => 'killykeen-forest-park', 'county' => 'Cavan', 'town' => 'Gowna', 'category' => 'Natureza', 'official_website' => '', 'discover_ireland' => '', 'excerpt' => 'Penínsulas florestais entre as ilhotas do Lough Oughter, com trilhas, caiaque e pesca.', 'content' => '<p>Killykeen se estende pelas águas rendilhadas do Lough Oughter, perto do castelo de mesmo nome. Trilhas planas, píeres de pesca e aluguel de caiaques fazem dele um destino de fim de semana tranquilo.</p>', 'outdoor' => true, 'free' => true ),
	array( 'title' => 'Dún a Rí Forest Park', 'slug' => 'dun-a-ri-forest-park', 'county' => 'Cavan', 'town' => 'Kingscourt', 'category' => 'Natureza', 'official_website' => '', 'discover_ireland' => '', 'excerpt' => 'Parque florestal com cabanas de gelo, ponte romana e lendas locais, nas margens do rio Cabra.', 'content' => '<p>Dún a Rí combina história e natureza: cabanas de gelo do século XVIII, uma ponte "romana", grutas e trilhas entre carvalhos e faías. Um dos parques florestais mais charmosos da região fronteiriça.</p>', 'outdoor' => true, 'family' => true, 'free' => true ),
	array( 'title' => 'Shannon Pot', 'slug' => 'shannon-pot', 'county' => 'Cavan', 'town' => 'Dowra', 'category' => 'Natureza', 'official_website' => '', 'discover_ireland' => '', 'excerpt' => 'Nascente do rio Shannon, o mais longo da Irlanda, num poço cárstico nas encostas do Cuilcagh.', 'content' => '<p>O Shannon Pot é onde o maior rio da Irlanda emerge do subsolo calcário. O sítio mítico, associado à deusa Sionna, fica numa paisagem remota de turfeira com plataforma de observação.</p>', 'outdoor' => true, 'free' => true ),
	array( 'title' => 'Cavan County Museum', 'slug' => 'cavan-county-museum', 'county' => 'Cavan', 'town' => 'Ballyjamesduff', 'category' => 'Museus', 'official_website' => '', 'discover_ireland' => 'https://www.discoverireland.ie/cavan/cavan-county-museum', 'excerpt' => 'Museu premiado com a maior réplica de trincheira da Primeira Guerra Mundial ao ar livre na Irlanda.', 'content' => '<p>Instalado num convento do século XIX, o Cavan County Museum destaca-se pela trincheira WWI em escala real construída nos jardins, além de coleções sobre história local e a Grande Fome.</p>', 'indoor' => true, 'outdoor' => true ),
	array( 'title' => 'Belturbet Railway Station', 'slug' => 'belturbet-railway-station', 'county' => 'Cavan', 'town' => 'Belturbet', 'category' => 'História', 'official_website' => '', 'discover_ireland' => '', 'excerpt' => 'Estação ferroviária de bitola estreita restaurada, com museu ferroviário e vagões de época.', 'content' => '<p>Belturbet foi entroncamento das linhas Cavan & Leitrim e Great Northern. O complexo restaurado inclui museu ferroviário, vagões originais e exposições sobre a era do trem na região.</p>', 'indoor' => true ),

	// ---- MONAGHAN (+6) ----
	array( 'title' => 'Castle Leslie Estate', 'slug' => 'castle-leslie-estate', 'county' => 'Monaghan', 'town' => 'Glaslough', 'category' => 'Castelos', 'official_website' => 'https://www.castleleslie.com/', 'discover_ireland' => 'https://www.discoverireland.ie/monaghan/castle-leslie-estate', 'excerpt' => 'Propriedade da família Leslie desde 1660, com castelo vitoriano, centro equestre, lago e trilhas.', 'content' => '<p>O Castle Leslie Estate combina hotel histórico com 1.000 acres de floresta, lagos e centro equestre abertos a visitantes diurnos. Paul McCartney celebrou aqui seu casamento em 2002.</p>', 'outdoor' => true, 'family' => true ),
	array( 'title' => 'Rossmore Forest Park', 'slug' => 'rossmore-forest-park', 'county' => 'Monaghan', 'town' => 'Monaghan', 'category' => 'Natureza', 'official_website' => '', 'discover_ireland' => 'https://www.discoverireland.ie/monaghan/rossmore-forest-park', 'excerpt' => 'Antiga propriedade dos Rossmore com trilhas, esculturas de madeira, lagos e ruínas de portais.', 'content' => '<p>Rossmore Forest Park oferece rotas fáceis entre lagos e bosques, com esculturas escondidas e os portais góticos da antiga mansão. Popular para corrida, passeios com cachorro e piqueniques.</p>', 'outdoor' => true, 'family' => true, 'free' => true ),
	array( 'title' => 'Monaghan County Museum', 'slug' => 'monaghan-county-museum', 'county' => 'Monaghan', 'town' => 'Monaghan', 'category' => 'Museus', 'official_website' => 'https://monaghan.ie/museum/', 'discover_ireland' => 'https://www.discoverireland.ie/monaghan/monaghan-county-museum', 'excerpt' => 'Primeiro museu de condado da Irlanda, premiado, com coleções sobre artesanato, conflitos e vida rural.', 'content' => '<p>Fundado em 1974, o Monaghan County Museum foi pioneiro no país e acumulou prêmios. Destaque para a coleção de renda de Carrickmacross e exposições sobre a história da região de fronteira.</p>', 'indoor' => true, 'free' => true ),
	array( 'title' => 'Carrickmacross Lace Gallery', 'slug' => 'carrickmacross-lace-gallery', 'county' => 'Monaghan', 'town' => 'Carrickmacross', 'category' => 'Cultura', 'official_website' => 'https://www.carrickmacrosslace.ie/', 'discover_ireland' => 'https://www.discoverireland.ie/monaghan/carrickmacross-lace-gallery', 'excerpt' => 'Ateliê e galeria da famosa renda de Carrickmacross, técnica usada no vestido de noiva de Diana, princesa de Gales.', 'content' => '<p>A Carrickmacross Lace Gallery mantém viva a tradição da renda irlandesa desde 1846. Visitantes veem artesãs trabalhando e podem comprar peças exclusivas feitas à mão.</p>', 'indoor' => true ),
	array( 'title' => 'Patrick Kavanagh Centre', 'slug' => 'patrick-kavanagh-centre', 'county' => 'Monaghan', 'town' => 'Inniskeen', 'category' => 'Cultura', 'official_website' => '', 'discover_ireland' => 'https://www.discoverireland.ie/monaghan/patrick-kavanagh-centre', 'excerpt' => 'Centro dedicado ao poeta Patrick Kavanagh na igreja antiga de Inniskeen, sua terra natal.', 'content' => '<p>Inniskeen inspirou a obra de Patrick Kavanagh, um dos maiores poetas irlandeses do século XX. O centro, instalado na antiga igreja, apresenta sua vida, poemas e a paisagem que ele eternizou.</p>', 'indoor' => true ),
	array( 'title' => 'Sliabh Beagh', 'slug' => 'sliabh-beagh', 'county' => 'Monaghan', 'town' => 'Knockatallon', 'category' => 'Caminhadas', 'official_website' => '', 'discover_ireland' => '', 'excerpt' => 'Planalto de turfeira na fronteira com a Irlanda do Norte, com trilhas, mirante e centro de visitantes.', 'content' => '<p>Sliabh Beagh ("montanha de Brehon") oferece caminhadas por turfeiras intocadas com vistas para seis condados. A rede de trilhas parte do Knockatallon Walkers\' Rest.</p>', 'outdoor' => true, 'free' => true ),
